        while (score < 3) {
            if (score < 3) {
                Gfx.Text(0, 0, "hi", 1.5f, 0);
                Gfx.Text(0, 0, "", 0);
            } else {
                score += 1;
            }
        }
    }

    static void Draw() {
        Gfx.Screen(Screen.Bottom);
    }
